        function ongetPatientDetailsSuccess(data) {

            if (data !== undefined) {
                if (data.Patient !== undefined) {
                    if (data.Patient.length > 0) {
                        var appointmentinfo = eHnoteMasterDataService.getAppointmentInfo();
                        appointmentinfo.PatientDetails.EmailId = data.PatientEmail[0].EmailId;
                        eHnoteMasterDataService.addAppointmentInfo(appointmentinfo);
                    }
                }               
                dischargeSummarySignFun();
            }
        }
        function ongetPatientDetailsError(error) {
            console.log(error);
        }
        $scope.SubTabChnages = function (value) {
            if ($scope.SubTab !== value) {
                /*                if ($scope.Tab == 2) {*/
                if ($scope.SubTab == 1) {
                    if (!$scope.obj.IsEditDischarge) {
                        $scope.DischargeSummaryObj.DischargeChartStatus = $scope.DischargeSummaryObj.DischargeChartStatus || 'D';
                        let str = '';
                        if ($scope.DischargeSummaryObj.DischargeChartStatus == 'E') {
                            /*str = 'SignOff';*/
                            alertify.error("Please Sign off Discharge Summary!");
                            return false;
                        }
                        $scope.SavePostOpDischargeData(str);
                    }
                }
                if ($scope.SubTab == 2) {
                    $scope.OperativeNotesObj.OperativeChartStatus = $scope.OperativeNotesObj.OperativeChartStatus || 'D';
                    if (!$scope.obj.IsEditOperativeNotes) {
                        let str = '';
                        if ($scope.OperativeNotesObj.OperativeChartStatus == 'E') {
                            /*str = 'SignOff';*/
                            alertify.error("Please Sign off Operative Notes!");
                            return false;
                        }
                        $scope.SaveOperativeNotes(str);
                    }
                }
                if (value != 0) {
                    $scope.SubTab = value;
                } else {
                    $scope.SubTab = 1;
                }

                //}
            }
            else if ($scope.SubTab == 0) {
                $scope.SubTab = 1;
            }

        }
