        function ComparePreOpVerification(NewValue, OldValue) {
            let count = 0;
            let OldAffecteditem = '';
            let Affecteditem = '';

            NewValue.forEach(function (Newitem) {
                let matchingOld = OldValue.find(function (olditem) {
                    olditem.Value = olditem.Value || "";
                    olditem.Remarks = olditem.Remarks || "";
                    return olditem.FaceSheetId == Newitem.FaceSheetId;
                });

                // If no matching old record or something changed
                if (!matchingOld ||
                    matchingOld.Value !== Newitem.Value ||
                    matchingOld.Remarks !== (Newitem.Remarks || "") ||
                    matchingOld.VerifiedUserId !== Newitem.VerifiedUserId) {

                    count++;

                    // --- Old Value ---
                    if (matchingOld) {
                        let oldDetails = `${matchingOld.FaceSheetName} : ${matchingOld.Value}`;
                        let oldusername = '';
                        var OldVerifiedByArraylist = $filter("filter")($scope.VerifiedByArray, function (vitem) { return vitem.DoctorID == matchingOld.VerifiedUserId });
                        if (OldVerifiedByArraylist.length > 0) {
                            oldusername = angular.copy(OldVerifiedByArraylist[0].FullName);
                        }
                        if (matchingOld.VerifiedUserId) {
                            oldDetails += `, Verified by : ${oldusername}`;
                        }
                        if (matchingOld.Remarks) {
                            oldDetails += `, Remarks : ${matchingOld.Remarks}`;
                        }
                        OldAffecteditem += `${OldAffecteditem ? '\n' : ''}${oldDetails}`;
                    }

                    // --- New Value ---
                    let newDetails = `${Newitem.FaceSheetName} : ${Newitem.Value}`;
                    let username = '';
                    var NewVerifiedByArraylist = $filter("filter")($scope.VerifiedByArray, function (vitem) { return vitem.DoctorID == Newitem.VerifiedUserId });
                    if (NewVerifiedByArraylist.length > 0) {
                        username = angular.copy(NewVerifiedByArraylist[0].FullName);
                    }
                    if (Newitem.VerifiedUserId) {
                        newDetails += `, Verified by : ${username}`;
                    }
                    if (Newitem.Remarks) {
                        newDetails += `, Remarks : ${Newitem.Remarks}`;
                    }
                    Affecteditem += `${Affecteditem ? '\n' : ''}${newDetails}`;
                }
            });

            if (count !== 0) {
                let obj = {
                    "LogId": 0,
                    "ModuleId": 2,
                    "ModuleName": "ASC",
                    "SubModuleId": 3,
                    "SubModuleName": "Facesheet",
                    "ScreenType": "ASC List",
                    "ActionType": "Edited",
                    "OldActionDescription": OldAffecteditem,
                    "NewActionDescription": Affecteditem,
                    "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                };
                $scope.LogObj.LogArray.push(obj);
            }
        }

