        function toEmptyString(value) {
            if (value == null || value == undefined) {
                return ''; // Convert null or undefined to empty string
            }
            return value; // Return other values as is
        }
        function toEmptybool(value) {
            if (value == null || value == undefined) {
                return false; // Convert null or undefined to empty string
            }
            return value;
        }
        function buildEyeDescription(item) {
            const od = `OD : ${toEmptyString(item.ODSphValue)} / ${toEmptyString(item.ODCylValue)} @ ${toEmptyString(item.ODAixValue)} `;
            const os = `OS : ${toEmptyString(item.OSSphValue)} / ${toEmptyString(item.OSCylValue)} @ ${toEmptyString(item.OSAixValue)}`;
            return `${od},${os}`;
        }
        function buildChangedKeratometryDescription(oldItem, newItem) {
            let oldDesc = '';
            let newDesc = '';
            const addLine = (label, oldVal, newVal) => {
                if (toEmptyString(oldVal.od) !== toEmptyString(newVal.od) || toEmptyString(oldVal.os) !== toEmptyString(newVal.os)) {
                    oldDesc += `${label} - OD : ${toEmptyString(oldVal.od)}, OS : ${toEmptyString(oldVal.os)}\n`;
                    newDesc += `${label} - OD : ${toEmptyString(newVal.od)}, OS : ${toEmptyString(newVal.os)}\n`;
                }
            };
            const addBoolLine = (label, oldOD, newOD, oldOS, newOS) => {
                let odChanged = toEmptybool(oldOD) !== toEmptybool(newOD);
                let osChanged = toEmptybool(oldOS) !== toEmptybool(newOS);


                if (odChanged) {
                    if (toEmptybool(oldOD)) oldDesc += `OD: ${label}\n`;
                    if (toEmptybool(newOD)) newDesc += `OD: ${label}\n`;
                }

                if (osChanged) {
                    if (toEmptybool(oldOS)) oldDesc += `OS: ${label}\n`;
                    if (toEmptybool(newOS)) newDesc += `OS: ${label}\n`;
                }

                //if (odChanged || osChanged) {
                //    if (toEmptybool(oldOD))
                //        oldDesc += `OD: ${label}\n`;
                //    if (toEmptybool(oldOS))
                //        oldDesc += `OS: ${label}\n`;

                //    if (toEmptybool(newOD))
                //        newDesc += `OD: ${label}\n`;
                //    if (toEmptybool(newOS))
                //        newDesc += `OS: ${label}\n`;
               // }
            };

            if (newItem.ODK1Value || newItem.OSK1Value || newItem.ODK1AxisValue || newItem.OSK1AxisValue) {
                addLine("K1", { od: oldItem.ODK1Value + " @ " + oldItem.ODK1AxisValue, os: oldItem.OSK1Value + " @ " + oldItem.OSK1AxisValue },
                    { od: newItem.ODK1Value + " @ " + newItem.ODK1AxisValue, os: newItem.OSK1Value + " @ " + newItem.OSK1AxisValue });
            }
            if (newItem.ODK2Value || newItem.OSK2Value || oldItem.ODK2AxisValue || newItem.OSK2AxisValue) {
                addLine("K2", { od: oldItem.ODK2Value + " @ " + oldItem.ODK2AxisValue, os: oldItem.OSK2Value + " @ " + oldItem.OSK2AxisValue },
                    { od: newItem.ODK2Value + " @ " + newItem.ODK2AxisValue, os: newItem.OSK2Value + " @ " + newItem.OSK2AxisValue });
            }

            addLine("Avg K Value", { od: oldItem.ODAvgKvalues, os: oldItem.OSAvgKvalues },
                { od: newItem.ODAvgKvalues, os: newItem.OSAvgKvalues });

            addLine("Astig", { od: oldItem.ODCylValue, os: oldItem.OSCylValue },
                { od: newItem.ODCylValue, os: newItem.OSCylValue });

            addLine("Axial Length", { od: oldItem.ODAxialLength, os: oldItem.OSAxialLength },
                { od: newItem.ODAxialLength, os: newItem.OSAxialLength });

            addLine("Optical ACD", { od: oldItem.ODOpticalACD, os: oldItem.OSOpticalACD },
                { od: newItem.ODOpticalACD, os: newItem.OSOpticalACD });

            addLine("WTW", { od: oldItem.ODWhitetoWhite, os: oldItem.OSWhitetoWhite },
                { od: newItem.ODWhitetoWhite, os: newItem.OSWhitetoWhite });

            addLine("Total Refraction", { od: oldItem.ODTargetRefraction, os: oldItem.OSTargetRefraction },
                { od: newItem.ODTargetRefraction, os: newItem.OSTargetRefraction });

           
            addLine("Remarks", { od: oldItem.ODRemarks, os: oldItem.OSRemarks },
                { od: newItem.ODRemarks, os: newItem.OSRemarks });
            addBoolLine("Immersion", oldItem.IsODImrChecked, newItem.IsODImrChecked, oldItem.IsOSImrChecked, newItem.IsOSImrChecked);
            addBoolLine("Pseudophakia", oldItem.IsODPsdChecked, newItem.IsODPsdChecked, oldItem.IsOSPsdChecked, newItem.IsOSPsdChecked);

            return {
                old: oldDesc.trim(),
                new: newDesc.trim()
            };
        }

        function buildChangedIolDescription(oldItem, newItem, IOLFaceSheetArray, Manufacturers) {
            let oldDesc = '';
            let newDesc = '';
            const getNameByType = (typeId, id) => {
                let match = $filter("filter")(IOLFaceSheetArray, function (item) {
                    return item.TypeId == typeId && item.IOLFaceSheetTypeId == id;
                });
                return (match.length > 0) ? match[0].IOLFaceSheetTypeName : id || '';
            };

            const getNameByManufacturer = (id) => {
                let match = $filter("filter")(Manufacturers, function (item) {
                    return item.ManufacturerId  == id;
                });
                return (match.length > 0) ? match[0].Manufacturer  : id || '';
            };
            
            const addLine = (label, oldVal, newVal) => {
                if (toEmptyString(oldVal.od) !== toEmptyString(newVal.od) || toEmptyString(oldVal.os) !== toEmptyString(newVal.os)) {
                    oldDesc += `${label} - OD : ${toEmptyString(oldVal.od)}, OS : ${toEmptyString(oldVal.os)}\n`;
                    newDesc += `${label} - OD : ${toEmptyString(newVal.od)}, OS : ${toEmptyString(newVal.os)}\n`;
                }
            };

            addLine("MFG", {
                od: getNameByManufacturer(oldItem.ODIOLManufacturerId),
                os: getNameByManufacturer(oldItem.OSIOLManufacturerId)
            },
                {
                    od: getNameByManufacturer(newItem.ODIOLManufacturerId),
                    os: getNameByManufacturer(newItem.OSIOLManufacturerId)
                });
            //addLine("MFG", { od: oldItem.ODIOLManufacturerId, os: oldItem.OSIOLManufacturerId },
            //    { od: newItem.ODIOLManufacturerId, os: newItem.OSIOLManufacturerId });

            addLine("Model number", { od: oldItem.ODIOLModel, os: oldItem.OSIOLModel },
                { od: newItem.ODIOLModel, os: newItem.OSIOLModel });

            addLine("Formula", {
                od: getNameByType(1, oldItem.ODFormulaId),
                os: getNameByType(1, oldItem.OSFormulaId)
            },
                {
                    od: getNameByType(1, newItem.ODFormulaId),
                    os: getNameByType(1, newItem.OSFormulaId)
                });

            addLine("Lasik/Radial", {
                od: getNameByType(3, oldItem.ODLasikTypeId),
                os: getNameByType(3, oldItem.OSLasikTypeId)
            },
                {
                    od: getNameByType(3, newItem.ODLasikTypeId),
                    os: getNameByType(3, newItem.OSLasikTypeId)
                });

            addLine("IOL SEQ", { od: oldItem.ODIOLpower, os: oldItem.OSIOLpower },
                { od: newItem.ODIOLpower, os: newItem.OSIOLpower });

            addLine("REF SEQ", { od: oldItem.ODTargetRefraction, os: oldItem.OSTargetRefraction },
                { od: newItem.ODTargetRefraction, os: newItem.OSTargetRefraction });


            addLine("Remarks", { od: oldItem.ODRemarks, os: oldItem.OSRemarks },
                { od: newItem.ODRemarks, os: newItem.OSRemarks });


            return {
                old: oldDesc.trim(),
                new: newDesc.trim()
            };
        }
        function generatePhysicalDescriptions(oldList, newList, oldNotes, newNotes) {
            let oldParts = [];
            let newParts = [];

            // Compare Dentition list
            newList.forEach(function (newItem) {
                let oldItem = oldList.find(item => item.Id === newItem.Id);
                if (!oldItem) {
                    newParts.push(newItem.Description);
                }
            });

            oldList.forEach(function (oldItem) {
                let newItem = newList.find(item => item.Id === oldItem.Id);
                if (!newItem) {
                    oldParts.push(oldItem.Description);
                }
            });

            // Compare Notes
            if ((oldNotes || '') !== (newNotes || '')) {
                if (oldNotes) oldParts.push(`Notes: ${oldNotes}`);
                if (newNotes) newParts.push(`Notes: ${newNotes}`);
            }

            return {
                oldDescription: oldParts.join(', '),
                newDescription: newParts.join(', ')
            };
        }
        function generateDentitionDescriptions(oldList, newList, oldNotes, newNotes) {
            let oldParts = [];
            let newParts = [];

            // Compare Dentition list
            newList.forEach(function (newItem) {
                let oldItem = oldList.find(item => item.DentitionId === newItem.DentitionId);
                if (!oldItem) {

                    $scope.HealthPhysicalObj.AirwayObj.Dentition = $scope.HealthPhysicalObj.AirwayObj.Dentition || '';
                    if (newItem.DentitionId == 22 && $scope.HealthPhysicalObj.AirwayObj.Dentition !=='') {
                        let AddItem = "";
                        AddItem = newItem.DentitionName + ':' + $scope.HealthPhysicalObj.AirwayObj.Dentition;
                        newParts.push(AddItem);
                    } else {
                        newParts.push(newItem.DentitionName);
                    }
                    
                }
            });

            oldList.forEach(function (oldItem) {
                let newItem = newList.find(item => item.DentitionId === oldItem.DentitionId);
                if (!newItem) {

                    $scope.LogObj.Dentition = $scope.LogObj.Dentition || '';
                    if (oldItem.DentitionId == 22 && $scope.LogObj.Dentition !== '') {
                        let EditItem = "";
                        EditItem = oldItem.DentitionName + ':' + $scope.LogObj.Dentition;
                        oldParts.push(EditItem);
                    } else {
                        oldParts.push(oldItem.DentitionName);
                    }
                    
                }
            });

            // Compare Notes
            if ((oldNotes || '') !== (newNotes || '')) {
                if (oldNotes) oldParts.push(`Notes: ${oldNotes}`);
                if (newNotes) newParts.push(`Notes: ${newNotes}`);
            }

            return {
                oldDescription: oldParts.join(', '),
                newDescription: newParts.join(', ')
            };
        }
        function generateDeltaDescriptions(oldList, newList, oldECG, newECG) {
            let oldParts = [];
            let newParts = [];

            // --- ECG VALUE + UNITS COMBINED ---
            const formatECGValue = (val, units) => {
                val = val || '';
                if (val == '') return '';
                return (val || '') + (units ? ' ' + units : '');
            };

            let oldECGValueCombined = formatECGValue(oldECG.ECG, oldECG.ECGUnits);
            let newECGValueCombined = formatECGValue(newECG.ECG, newECG.ECGUnits);

            if (oldECGValueCombined !== newECGValueCombined) {
                if (oldECGValueCombined != '') {
                    oldParts.push('ECGValue: ' + oldECGValueCombined);
                }
                if (newECGValueCombined != '') {
                    newParts.push('ECGValue: ' + newECGValueCombined);
                }
            }

            // ECG Notes
            if ((oldECG.ECGNotes || '') !== (newECG.ECGNotes || '')) {
                if (oldECG.ECGNotes != '') {
                    oldParts.push('ECGNotes: ' + (oldECG.ECGNotes || ''));
                }
                if (newECG.ECGNotes != '') {
                    newParts.push('ECGNotes: ' + (newECG.ECGNotes || ''));
                }
            }

            // --- LAB VALUES COMPARISON ---
            newList.forEach(function (newItem) {
                let oldItem = oldList.find(item => item.ProcedureId === newItem.ProcedureId);

                let procName = '';
                let newRemarks = '';
                if (newItem.ProcedureId === 849) {
                    procName = 'PT';
                } else if (newItem.ProcedureId === 850) {
                    procName = 'PTT';
                } else {
                    procName = newItem.ProcedureName;
                }
                let resultDisplay = newItem.ResultValue || '';
                if (newItem.ProcedureId === 849 || newItem.ProcedureId === 850) {
                    if (newItem.Normal === true) {
                        resultDisplay += ' (WNL)';
                    } else if (newItem.AbNormal === true) {
                        resultDisplay += ' (Abnormal)';
                    }
                }

                if (newItem.Remarks) {
                    newRemarks = ', Notes :' + newItem.Remarks
                }
                if (
                    !oldItem ||
                    oldItem.ResultValue !== newItem.ResultValue ||
                    oldItem.Remarks !== newItem.Remarks ||
                    oldItem.AbNormal !== newItem.AbNormal ||
                    oldItem.Normal !== newItem.Normal
                ) {
                    if (oldItem) {
                        let oldProcName = '';
                        let oldRemarks = '';
                        if (oldItem.ProcedureId === 849) {
                            oldProcName = 'PT';
                        } else if (oldItem.ProcedureId === 850) {
                            oldProcName = 'PTT';
                        } else {
                            oldProcName = oldItem.ProcedureName;
                        }


                        let oldResultDisplay = oldItem.ResultValue || '';
                        if (oldItem.ProcedureId === 849 || oldItem.ProcedureId === 850) {
                            if (oldItem.Normal === true) {
                                oldResultDisplay += ' (WNL)';
                            } else if (oldItem.AbNormal === true) {
                                oldResultDisplay += ' (Abnormal)';
                            }
                        }

                        if (oldItem.Remarks) {
                            oldRemarks = ', Notes :' + oldItem.Remarks
                        }

                        oldParts.push(`${oldProcName}: ${oldResultDisplay} ${oldRemarks}`);
                        newParts.push(`${procName}: ${resultDisplay} ${newRemarks}`);
                    } else {
                        newParts.push(`${procName}: ${resultDisplay} ${newRemarks}`);
                    }
                }
            });

            return {
                oldDescription: oldParts.join(', '),
                newDescription: newParts.join(', ')
            };
        }
        function generateChemistryDescriptions(oldList, newList, oldNotes, newNotes) {
            let oldParts = [];
            let newParts = [];

            newList.forEach(function (newItem) {
                let oldItem = oldList.find(item => item.ProcedureId === newItem.ProcedureId);

                if (!oldItem || oldItem.ResultValue !== newItem.ResultValue) {
                    if (oldItem) oldParts.push(`${oldItem.ProcedureName}: ${oldItem.ResultValue}`);
                    newParts.push(`${newItem.ProcedureName}: ${newItem.ResultValue}`);
                }
            });

            // Compare Chemistry Notes
            if ((oldNotes || '') !== (newNotes || '')) {
                if (oldNotes) oldParts.push(`ChemistryNotes: ${oldNotes}`);
                if (newNotes) newParts.push(`ChemistryNotes: ${newNotes}`);
            }

            return {
                oldDescription: oldParts.join(', '),
                newDescription: newParts.join(', ')
            };
        }
        $scope.findHandPDifferences = function (savedArray, editedArray) {
            var differences = [];
            /* var maxLength = Math.max(arr1.length, arr2.length);*/

            angular.forEach(savedArray, function (item) {
                //  item.ChecklistDate = item.ChecklistDate || null;
                item.Remarks = item.Remarks || '';

                var edited = editedArray.filter(function (eitem) {
                    //  eitem.ChecklistDate = eitem.ChecklistDate || null;
                    eitem.Remarks = eitem.Remarks || '';

                    return ((eitem.HistoryId == item.HistoryId) && (item.TypeId == eitem.TypeId) && (item.Value == eitem.Value) && (item.Remarks == eitem.Remarks) && (item.DeleteInd == eitem.DeleteInd));
                }) || [];


                if (edited.length == 0) {
                    differences.push({
                        HistoryId: item.HistoryId,
                        TypeId: item.TypeId,
                        HistoryName: item.HistoryName,
                        Value: item.Value,
                    });
                    /*count++;*/
                }

            });
            //editedArray.forEach(function (editedItem) {

            return differences;
        };


