        function buildInvestigationDescription(oldItem, newItem, getLocationName) {
            let oldparts = [];
            let newparts = [];
            const formatDuration = (value, type) => {
                if (!value) return '';
                const labels = { Y: 'Year(s)', W: 'Week(s)', M: 'Month(s)', D: 'Day(s)', H: 'Hour(s)' };
                return `${value} ${labels[type] || ''}`;
            };
            const formatDate = (date) => {
                return date ? $filter("date")(date, "MM-dd-yyyy") : "";
            };
                if (newItem?.InvestigationName) newparts.push("Investigation  : " + newItem.InvestigationName);
               if (oldItem?.InvestigationName) oldparts.push("Investigation  : " + oldItem.InvestigationName);
            if (newItem?.LocationId != oldItem?.LocationId) {
                let newLoc = getLocationName(newItem?.LocationId);
                let oldLoc = getLocationName(oldItem?.LocationId);
                if (newLoc) newparts.push("Location: " + newLoc);
                if (oldLoc) oldparts.push("Location: " + oldLoc);
            }
            if (newItem?.DurationDate != oldItem?.DurationDate) {
                if (newItem?.DurationDate) newparts.push("Duration Date : " + formatDate(newItem.DurationDate));
                if (oldItem?.DurationDate) oldparts.push("Duration Date : " + formatDate(oldItem.DurationDate));
            }
            //if (newItem?.DurationDate) newparts.push("Duration Date: " + newItem.DurationDate);
            //if (oldItem?.DurationDate) oldparts.push("Duration Date: " + oldItem.DurationDate);

            if ((newItem?.Duration != oldItem?.Duration) || (newItem?.DurationType != oldItem?.DurationType)) {
                var newDuration = formatDuration(newItem?.Duration, newItem?.DurationType);
                var oldDuration = formatDuration(oldItem?.Duration, oldItem?.DurationType);
            }
            if (newDuration !== oldDuration) {
                if (newDuration) newparts.push("Duration : " + newDuration);
                if (oldDuration) oldparts.push("Duration : " + oldDuration);
            }
            if (newItem?.InvestigationNotes != oldItem?.InvestigationNotes) {
                if (newItem?.InvestigationNotes) newparts.push("Investigation Notes : " + newItem.InvestigationNotes);
                if (oldItem?.InvestigationNotes) oldparts.push("Investigation Notes : " + oldItem.InvestigationNotes);
            }
            return {
                newDesc: newparts.join(","),
                oldDesc: oldparts.join(",")
            };
        }
        function buildDiagnosisDescription(oldItem, newItem, getLocationName, getSeverityName, getStatusName) {
            let newParts = [];
            let oldParts = [];

            if (newItem?.ICDCode || newItem?.DiagnosisName) {
                newParts.push(`Diagnosis  : ${newItem?.ICDCode || ""}- ${newItem?.DiagnosisName || ""}`);
            }

            if (newItem?.LocationId1 || newItem?.SeverityId1 || newItem?.DiagnosisStatusId1) {
                if (newItem?.LocationId1) newParts.push(`Location-1 : ${getLocationName(newItem?.LocationId1)}`);
                if (newItem?.SeverityId1) newParts.push(`Severity-1 : ${getSeverityName(newItem?.SeverityId1)}`);
                if (newItem?.DiagnosisStatusId1) newParts.push(`Status-1 : ${getStatusName(newItem?.DiagnosisStatusId1)}`);
            }

            if (newItem?.LocationId2 || newItem?.SeverityId2 || newItem?.DiagnosisStatusId2) {
                if (newItem?.LocationId2) newParts.push(`Location-2 : ${getLocationName(newItem?.LocationId2)}`);
                if (newItem?.SeverityId2) newParts.push(`Severity-2 : ${getSeverityName(newItem?.SeverityId2)}`);
                if (newItem?.DiagnosisStatusId2) newParts.push(`Status-2 : ${getStatusName(newItem?.DiagnosisStatusId2)}`);
            }

            if (oldItem?.ICDCode || oldItem?.DiagnosisName) {
                oldParts.push(`Diagnosis  : ${oldItem?.ICDCode || ""}- ${oldItem?.DiagnosisName || ""}`);
            }

            if (oldItem?.LocationId1 || oldItem?.SeverityId1 || oldItem?.DiagnosisStatusId1) {
                if (oldItem.LocationId1) oldParts.push(`Location-1 : ${getLocationName(oldItem?.LocationId1)}`);
                if (oldItem?.SeverityId1) oldParts.push(`Severity-1 : ${getSeverityName(oldItem?.SeverityId1)}`);
                if (oldItem?.DiagnosisStatusId1) oldParts.push(`Status-1 : ${getStatusName(oldItem?.DiagnosisStatusId1)}`);
            }

            if (oldItem?.LocationId2 || oldItem?.SeverityId2 || oldItem?.DiagnosisStatusId2) {
                if (oldItem?.LocationId2) oldParts.push(`Location-2 : ${getLocationName(oldItem?.LocationId2)}`);
                if (oldItem?.SeverityId2) oldParts.push(`Severity-2 : ${getSeverityName(oldItem?.SeverityId2)}`);
                if (oldItem?.DiagnosisStatusId2) oldParts.push(`Status-2 : ${getStatusName(oldItem?.DiagnosisStatusId2)}`);
            }

            return {
                newDesc: newParts.join(", "),
                oldDesc: oldParts.join(", ")
            };
        }
        function buildOcularHistoryDescription(oldItem, newItem, $filter) {
            let oldparts = [];
            let newparts = [];

            const formatDuration = (value, type) => {
                if (!value) return '';
                const labels = { Y: 'Year(s)', W: 'Week(s)', M: 'Month(s)', D: 'Day(s)', H: 'Hour(s)' };
                return `${value} ${labels[type] || ''}`;
            };
            const formatDate = (date) => {
                return date ? $filter("date")(date, "MM-dd-yyyy") : "";
            };

            // History Name
            if (newItem?.HistoryName) newparts.push("History : " + newItem.HistoryName);
            if (oldItem?.HistoryName) oldparts.push("History : " + oldItem.HistoryName);

            // Left Eye Duration + Date
            if (newItem?.LDuration != oldItem?.LDuration || newItem?.LDurationType != oldItem?.LDurationType) {
                let newDur = formatDuration(newItem?.LDuration, newItem?.LDurationType);
                let oldDur = formatDuration(oldItem?.LDuration, oldItem?.LDurationType);
                if (newDur) newparts.push("OS Duration : " + newDur);
                if (oldDur) oldparts.push("OS Duration : " + oldDur);
            }
            if (newItem?.LDurationDate != oldItem?.LDurationDate) {
                if (newItem?.LDurationDate) newparts.push("OS DurationDate : " + formatDate(newItem.LDurationDate));
                if (oldItem?.LDurationDate) oldparts.push("OS DurationDate : " + formatDate(oldItem.LDurationDate));
            }

            // Right Eye Duration + Date
            if (newItem?.RDuration != oldItem?.RDuration || newItem?.RDurationType != oldItem?.RDurationType) {
                let newDur = formatDuration(newItem?.RDuration, newItem?.RDurationType);
                let oldDur = formatDuration(oldItem?.RDuration, oldItem?.RDurationType);
                if (newDur) newparts.push("OD Duration : " + newDur);
                if (oldDur) oldparts.push("OD Duration : " + oldDur);
            }
            if (newItem?.RDurationDate != oldItem?.RDurationDate) {
                if (newItem?.RDurationDate) newparts.push("OD DurationDate : " + formatDate(newItem.RDurationDate));
                if (oldItem?.RDurationDate) oldparts.push("OD DurationDate : " + formatDate(oldItem.RDurationDate));
            }
            // Severity
            if (newItem?.RSeverityName != oldItem?.RSeverityName) {
                if (newItem?.RSeverityName) newparts.push("OD Severity : " + newItem.RSeverityName);
                if (oldItem?.RSeverityName) oldparts.push("OD Severity : " + oldItem.RSeverityName);
            }
            if (newItem?.LSeverityName != oldItem?.LSeverityName) {
                if (newItem?.LSeverityName) newparts.push("OS Severity: " + newItem.LSeverityName);
                if (oldItem?.LSeverityName) oldparts.push("OS Severity: " + oldItem.LSeverityName);
            }

            // Status
            if (newItem?.RStatusName != oldItem?.RStatusName) {
                if (newItem?.RStatusName) newparts.push("OD Status : " + newItem.RStatusName);
                if (oldItem?.RStatusName) oldparts.push("OD Status : " + oldItem.RStatusName);
            }
            if (newItem?.LStatusName != oldItem?.LStatusName) {
                if (newItem?.LStatusName) newparts.push("OS Status : " + newItem.LStatusName);
                if (oldItem?.LStatusName) oldparts.push("OS Status : " + oldItem.LStatusName);
            }
            if (newItem?.Remarks != oldItem?.Remarks) {
                if (newItem?.Remarks) newparts.push("Remarks : " + newItem.Remarks);
                if (oldItem?.Remarks) oldparts.push("Remarks : " + oldItem.Remarks);
            }

            if ($scope.obj.OccularHistoryRemarks != $scope.LogObj.OccularHistoryRemarks) {
                if ($scope.obj.OccularHistoryRemarks)
                    newparts.push("Occular History Notes : " + $scope.obj.OccularHistoryRemarks);

                if ($scope.LogObj.OccularHistoryRemarks)
                    oldparts.push("Occular History Notes : " + $scope.LogObj.OccularHistoryRemarks);
            }
            return {
                newDesc: newparts.join(", "),
                oldDesc: oldparts.join(", ")
            };
        }

