                    "Pathology": $scope.DischargeSummaryObj.Pathology || '',
                    "ImplantsDetailsArray": $scope.DischargeSummaryObj.ImplantsDetailsArray || [],
                    "FinalDisposition": $scope.DischargeSummaryObj.FinalDisposition || '',
                    "OthersDetailsArray": $scope.OperativeNotesObj.OthersDetailsArray || [],

                    "PatientSignString": $scope.DischargeSummaryObj.PatientSignString || '',
                    "NurseSignString": $scope.DischargeSummaryObj.NurseSignString || '',
                    "AccompaniedBySignString": $scope.DischargeSummaryObj.AccompaniedBySignString || '',
                    "PatientSignedDateTime": $scope.DischargeSummaryObj.PatientSignedDateTime || null,
                    "NurseSignedDateTime": $scope.DischargeSummaryObj.NurseSignedDateTime || null,
                    "AccompaniedByDateTime": $scope.DischargeSummaryObj.AccompaniedByDateTime || null,
                    "SignaturePatientName": $scope.cacheStorageItem.PatientName || '',
                    "SignatureNurseName": $scope.DischargeSummaryObj.SignatureNurseName || '',
                    "AccompainedBy": $scope.DischargeSummaryObj.AccompainedBy || '',
                    "AccompainedByNotes": $scope.DischargeSummaryObj.AccompainedByNotes || '',
