        function convertTo24Hour(time12h) {
            const [time, modifier] = time12h.split(" ");
            let [hours, minutes] = time.split(":");

            hours = parseInt(hours);
            if (modifier === "PM" && hours !== 12) {
                hours += 12;
            }
            if (modifier === "AM" && hours === 12) {
                hours = 0;
            }

            return `${String(hours).padStart(2, '0')}:${minutes}`;
        }

        $scope.PostOpDischargeSignOff = function (str) {

            if ($scope.DischargeSummaryObj.DischargeTime !== '' && !$scope.DischargeSummaryObj.IsForceEarlySignOff) {
                const now = new Date();
                const timeStr = $scope.DischargeSummaryObj.DischargeSignOffStartTime;

                if (timeStr && typeof timeStr === 'string' && timeStr.includes(":")) {
                    const time24 = convertTo24Hour(timeStr);
                    const parsedStartTime = new Date(`1970-01-01T${time24}:00`);

                    const startTime = new Date(now);
                    startTime.setHours(parsedStartTime.getHours(), parsedStartTime.getMinutes(), 0, 0);

                    if (startTime > now) {
                        startTime.setDate(startTime.getDate() - 1);
                    }

                    const diffMs = now - startTime;
                    const totalMinutes = Math.floor(diffMs / (1000 * 60));

                    var timeDifferenceInMinutes = totalMinutes;

                    var DischargeTime = parseFloat($scope.DischargeSummaryObj.DischargeTime);

                    if (timeDifferenceInMinutes < DischargeTime) {
                        alertify.error("Discharge timer not completed yet");
                        return false;
                    }
                } else {
                    alertify.error("Discharge timer not started yet");
                    return false;
                }
            }

            let DischargeAutosighnoff = false;

            //if ($scope.RoleId == 1 || $scope.RoleId == 43) {

            //    DischargeAutosighnoff = true;
            //}

            if (doctorinfo.RoleID == 8) {
                var UserType = 'Nurse'
            }
            else {
                var UserType = 'Surgeon'
            }
            let obj = {
                "Screen": "Discharge",
                "Type": "SignOff",
                "UserType": UserType,
                "allUserList": angular.copy($scope.allUserList) || [],
                "IsAutoSighnOff": DischargeAutosighnoff || false
            };

            let signmodalInstance = $uibModal.open({
                "templateUrl": "templates/consultation/SignOffPasswordNew.html",
                "controller": "UsSignOffPasswordPopupCtrl",
                "size": "md",
                "windowClass": " ",
                "backdrop": "static",
                "keyboard": false,
                "resolve": {
                    "obj": function () { return obj; }
                }
            });
            signmodalInstance.result.then(function (resp) {
                let UserObj = $filter("filter")($scope.allUserList, function (kitem) { return kitem.DoctorID == resp.DoctorId }, true) || [];
                $scope.SignOffUserName = UserObj.length > 0 ? (UserObj[0].UserFullName ) || "" : "";
                $scope.SignOffUserId = UserObj.length > 0 ? UserObj[0].LicenseNumber || "" : "";
                if ($scope.DischargeSummaryObj.DischargeReviewedBy == null) {
                    $scope.DischargeSummaryObj.DischargeReviewedBy = resp.DoctorId || null
                }
                $scope.SavePostOpDischargeData("SignOff");
            }, function (data) {

            });
        }
