        $scope.SaveOperativeNoteAddendum = function (signResp) {
            let SelectedReason = $filter("filter")($scope.OperativeNoteAddendumReasons, { "AddendumReasonId": $scope.OperativeNoteAddendumObj.AddendumReasonId }, true) || [];
            let obj = {
                "AppointmentId": $scope.FaceSheetAppointmentId || null,
                "VisitId": $scope.cacheStorageItem.PatientVisitId,
                "PatientId": $scope.cacheStorageItem.PatientID || null,
                "HospitalId": $scope.HospitalId || null,
                "UserId": $scope.UserId || null,
                "OperativeNoteAddendum": [
                    {
                        "PatientOperativeNotesId": $scope.OperativeNotesObj.PatientOperativeNotesId || 0,
                        "AddendumReasonId": $scope.OperativeNoteAddendumObj.AddendumReasonId,
                        "AddendumReasonName": SelectedReason.length > 0 ? (SelectedReason[0].AddendumReasonName || "") : "",
                        "AddendumText": $scope.OperativeNoteAddendumObj.AddendumText,
                        "AuthoredByUserId": $scope.UserId || null,
                        "SignedByUserId": signResp.DoctorId || null,
                        "DeleteInd": "N",
                    }
                ],
            };
            $scope.OperativeNoteAddendumObj.IsClickSaveAddendumBtn = true;
            eHnoteSurgeryService.AddOperativeNoteAddendum(obj).then(function (resp) {
                if (resp.data.Status == "Success") {
                    alertify.success("Addendum Added successfully!");
                    let UserObj = $filter("filter")($scope.allUserList, function (kitem) { return kitem.DoctorID == signResp.DoctorId }, true) || [];
                    let FullName = UserObj.length > 0 ? (UserObj[0].UserFullName) || "" : "";
                    let LicenseNumber = UserObj.length > 0 ? UserObj[0].LicenseNumber || "" : "";
                    $scope.AddAuditLog({
                        "SubModuleId": 5,
                        "SubModuleName": "Operative notes",
                        "ScreenType": "Addendum",
                        "ActionType": "Added",
                        "NewActionDescription": `Operative notes addendum signed by ${FullName}, Lic : ${LicenseNumber}`,
                    });
                    $scope.OperativeNoteAddendumObj = $scope.GetOperativeNoteAddendumObj();
                    $scope.init();
                } else {
                    $scope.OperativeNoteAddendumObj.IsClickSaveAddendumBtn = false;
                    alertify.error(resp.data.Message);
                }
            }, function () {
                $scope.OperativeNoteAddendumObj.IsClickSaveAddendumBtn = false;
                alertify.error("Unable to save addendum. Please try again.");
            });
        }

