        $scope.getpatientDrawingfiles = function () {
            var params = {
                "AppointmentId": $scope.FaceSheetAppointmentId,
                "RequestType": "ASC"
            }
            eHnotePatientDataService.getPatientASCDrawingPadImages(params).then(function (resp) {
                console.log(resp);
                if (resp.data.rows.length > 0) {
                    $scope.patientAscDrawingfiles = resp.data.rows;
                    $scope.DrawingPadImgs();
                }
            }, function (err) {
                alertify.error(err.Messege);
            });

        };
        $scope.getpatientDrawingfiles();

        $scope.DrawingPadImagesArray = [];
        $scope.DrawingPadImgs = function () {
            if ($scope.patientAscDrawingfiles.length > 0) {
                angular.forEach($scope.patientAscDrawingfiles, function (item, index) {
                    if (index < 2) {
                        if (item.S3URL !== '') {
                            $scope.toDataURL(item.S3URL, function (dataURL) {
                                $scope.DrawingPadImagesArray.push(dataURL);
                            });
                        }
                    }
                });
            }
        }

        $scope.obj.selectedpentaCamReportImages = "";
        $scope.file = null;

        $scope.currentPentaCamReports = [];



        function getNewPentaCamAddObj() {
            var obj = {
                "HospitalId": $scope.HospitalId || 0,
                "UserId": $scope.UserId,
                "PatientId": $scope.cacheStorageItem.PatientID || 0,
                "AppointmentId": $scope.FaceSheetAppointmentId,
                "PatientName": $scope.cacheStorageItem.PatientName || "Patient",
                "PentaCamReportDocuments": []
            };

            return obj;
        }

        $scope.pentaCamReportAddObj = getNewPentaCamAddObj();

        $scope.selectPentaCamImage = function ($files) {


            $scope.file = "";
            $scope.currentPentaCamReports = [];
            $scope.file = $files;

            if ($scope.file != null) {
                if ($scope.file.length > 0) {
                    angular.forEach($scope.file, function (fitem) {
                        var pName = fitem.name, name = "";
                        var type = fitem.type.split("/")[1];
                        if (pName.length > 9) {
                            name = pName.substring(0, 9) + "..." + "." + type;
                        } else {
                            name = angular.copy(pName) + '.' + type;
                        }
                        let organid = $scope.SelectedOrganId || 1;
                        var SelectedDate = $filter("date")(new Date(), "yyyy-MM-dd");
                        var obj = {
                            "file": fitem,
                            "FileTypeId": 36,
                            "S3URL": "",
                            "Remarks": "",
                            "DeleteInd": "N",
                            "OrganId": organid,
                            "DocumentId": 0,
                            "SignedDate": SelectedDate,
                            "DisplayName": fitem.name || "",
                            "DocumentName": fitem.name || "",
                            "FileName": fitem.name || "",
                            "DocumentExt": fitem.type,
                            "FileExt": fitem.type,
                        };
                        $scope.currentPentaCamReports.push(obj);

                    });
                }
            };

            $scope.obj.selectedpentaCamReportImages = "";
            $scope.PatientPentaCamReportSave($scope.currentPentaCamReports);
        };

        $scope.RemovePentaCamReport = function (item, index) {

            if (item.PatientPCPDocumentId != 0) {
                var DeleteFileUploadArray = { "DocumentID": item.DocumentId, "FileName": item.DocumentName, "Remarks": "" };
                alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure you want to delete? </h4>", function () {
                    var params = {
                        "AppointmentID": $scope.FaceSheetAppointmentId,
                        "DeleteIndicator": 0,
                        "ImagesArray": [],
                        "UploadType": "Delete",
                        "HospitalID": $scope.HospitalId,
                        "Remarks": "",
                        "Logs": {}
                    };
                    $scope.LogObj.LogArray = [];
                    params.ImagesArray.push(DeleteFileUploadArray);
                    if (params.ImagesArray.length > 0) {
                        let obj = {
                            "LogId": 0,
                            "ModuleId": 2,
                            "ModuleName": "ASC",
                            "SubModuleId": 3,
                            "SubModuleName": "Facesheet",
                            "ScreenType": "ASC List",
                            "ActionType": "Deleted",
                            "OldActionDescription": params.ImagesArray[0].FileName + " Facesheet screen",
                            "NewActionDescription": "",
                            //"ActionDescription": `Files are Deleted In Facesheet screen For AppointmentId : ${$scope.cacheStorageItem.AppointmentId}`,
                            "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                        };
                        $scope.LogObj.LogArray.push(obj);
                    }
                    params.Logs = angular.copy($scope.LogObj) || {};
                    eHnoteDiagnosisDataServices.DeletePatientConsultationImg(params, onupdateDeletesuccess, onupdateDelerror)
                    function onupdateDeletesuccess(resp) {
                        console.log(resp);
                        $scope.pentaCamReportImages.splice(index, 1);

                    }
                    function onupdateDelerror(error) {
                        console.log(error);

                    }
                }, function () { });
            }
            else {
                $scope.pentaCamReportImages.splice(index, 1);
            }
        }

        $scope.scanPentaCamReport = function () {

            var obj = {
                "PatientId": $scope.cacheStorageItem.PatientID || 0,
                "AppointmentId": $scope.FaceSheetAppointmentId,
                "PatientName": $scope.cacheStorageItem.PatientName || ''
            }
            $scope.currentPentaCamReports = [];
            $scope.mInstanceAdd = $uibModal.open({
                "templateUrl": "templates/UsNewConsultation/uibpopup/PatientDocumentScanner.html",
                "backdrop": "static",
                "size": "md",
                "resolve": {
                    "mainObject": function () { return obj; }
                },
                "windowClass": "modal__eighty-- zindexpopup  ",
                "keyboard": false,
                "controller": "DocumentScannerCtrl",
            });
            $scope.mInstanceAdd.result.then(function (result) {
                if (result !== "") {
                    var SelectedDate = $filter("date")(new Date(), "yyyy-MM-dd");
                    var obj = {
                        "DocumentId": 0,
                        "DocumentExt": result.FileExt,
                        "FileExt": result.FileExt,
                        "DocumentName": result.DocumentName,
                        "FileName": result.DocumentName,
                        "S3URL": result.S3URL,
                        "OrganId": 1,
                        "DeleteInd": "N",
                        "FileTypeId": 36,
                        "SignedDate": SelectedDate,
                        "DisplayName": result.DocumentName || "",
                        "Remarks": "",
                    }
                    $scope.currentPentaCamReports.push(obj);


                    $scope.PatientPentaCamReportSave($scope.currentPentaCamReports);
                }
            }, function (cancel) {
            });

        }

        $scope.PatientPentaCamReportSave = function (data) {
            $scope.LogObj.LogArray = [];
            var params = {
                "UserId": $scope.pentaCamReportAddObj.UserId,
                "HospitalId": $scope.pentaCamReportAddObj.HospitalId,
                "PatientId": $scope.pentaCamReportAddObj.PatientId,
                "VisitId": $scope.cacheStorageItem.PatientVisitId,
                "AppointmentId": $scope.pentaCamReportAddObj.AppointmentId,
                "PatientName": $scope.pentaCamReportAddObj.PatientName,
                "PentaCamReportDocuments": data,
                "Logs": {}
            }
            if (params.PentaCamReportDocuments.length > 0) {
                let obj = {
                    "LogId": 0,
                    "ModuleId": 2,
                    "ModuleName": "ASC",
                    "SubModuleId": 3,
                    "SubModuleName": "Facesheet",
                    "ScreenType": "ASC List",
                    "ActionType": "Imported",
                    "OldActionDescription": "",
                    //"NewActionDescription": params.PentaCamReportDocuments[0].DisplayName + " Files are Uploaded  In Facesheet screen ",
                    "NewActionDescription": params.PentaCamReportDocuments[0].DisplayName+" Uploaded  In Facesheet screen",
                    "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                };
                $scope.LogObj.LogArray.push(obj);
            }
            params.Logs = angular.copy($scope.LogObj) || {};
            eHnotePatientDataService.AddUpdatePatientPentaCamReport(params, OnAddPatientSuccess, OnAddPatientError);
            function OnAddPatientSuccess(resp) {

                console.log(resp);
                $scope.pentaCamReportImages = [];
                if (resp.Status === "Success") {
                    if (resp.PentaCamReportDocuments.length > 0) {
                        angular.forEach(resp.PentaCamReportDocuments, function (pitem) {
                            var obj = {
                                "DocumentId": pitem.FileId,
                                "DocumentExt": pitem.FileExt,
                                "FileExt": pitem.FileExt,
                                "DocumentName": pitem.FileName,
                                "FileName": pitem.FileName,
                                "S3URL": pitem.S3URL,
                                "OrganId": pitem.OrganId,
                                "DeleteInd": "N",
                                "FileTypeId": 36,
                                "DisplayName": pitem.FileName || "",
                            }
                            $scope.pentaCamReportImages.push(obj);
                        });
                    }

                };


                $scope.cacheStorageItem.CopiedPreviousAppointmentId = $scope.cacheStorageItem.CopiedPreviousAppointmentId || 0;
                $scope.cacheStorageItem.PreAdmAppointmentId = $scope.cacheStorageItem.PreAdmAppointmentId || 0;

                if ($scope.cacheStorageItem.CopiedPreviousAppointmentId !== 0) {
                    $scope.GetAppointmentImages($scope.cacheStorageItem.CopiedPreviousAppointmentId);
                }
                if ($scope.cacheStorageItem.PreAdmAppointmentId !== 0) {
                    $scope.GetAppointmentImages($scope.cacheStorageItem.PreAdmAppointmentId);
                };



            }
            function OnAddPatientError() {
                alertify.error("Creating  Failed");
            }
        };







