        $scope.SaveFinaldispositionTemplateData = function () {
            $scope.Templateobj.EnterFinaldispositionTemplateName = $scope.Templateobj.EnterFinaldispositionTemplateName || "";
            $scope.DischargeSummaryObj.FinalDisposition = $scope.DischargeSummaryObj.FinalDisposition || "";
            if ($scope.Templateobj.EnterFinaldispositionTemplateName === "") {
                alertify.error("Please Enter Template Name!");
                return false;
            }
            if ($scope.DischargeSummaryObj.FinalDisposition === "") {
                alertify.error("Please Enter Final Disposition");
                return false;
            }
            let templateReq = {
                "UserId": $scope.UserId || "",
                "HospitalId": $scope.HospitalId || "",
                "TemplateId": 0,
                "TemplateName": $scope.Templateobj.EnterFinaldispositionTemplateName || "",
                "DeleteInd": "N",
                "TemplateNotes": $scope.DischargeSummaryObj.FinalDisposition || "",
                "TypeId": '11',
                "TypeName": 'Finaldisposition',
            };


            eHnoteSurgeryService.AddUpdateIntraOpTemplates(templateReq).then(function (resp) {
                if (resp.data.Status === "Success") {
                    alertify.success("Template saved successfully!");
                    $scope.Templateobj.EnterFinaldispositionTemplateName = "";
                    $scope.Templateobj.IsFinaldispositionTemplateSavePopOver = false;
                    $scope.GetPreOpMedicineCheckListTemplates();

                }
                if (resp.data.status === "Failure") {
                    alertify.error('TemplateName Already Exists')
                }
            }, function (err) {
                console.log(err);
            });
        };


        $scope.OnselectPhysicalTemplates = function (item) {
            item.TemplateNotes = item.TemplateNotes || "";
            if (item.TemplateNotes != '') {
                $scope.OperativeNotesObj.PhysicalExam = item.TemplateNotes || "";
            }
            else {
                $scope.OperativeNotesObj.PhysicalExam = '';
            }
        };
        $scope.OnselectPathologyTemplates = function (item, type) {
            item.TemplateNotes = item.TemplateNotes || "";

            if (type == 'Discharge') {
                if (item.TemplateNotes != '') {
                    $scope.DischargeSummaryObj.Pathology = item.TemplateNotes || "";
                }
                else {
                    $scope.DischargeSummaryObj.Pathology = '';
                }
            } else {
                if (item.TemplateNotes != '') {
                    $scope.OperativeNotesObj.Pathology = item.TemplateNotes || "";
                }
                else {
                    $scope.OperativeNotesObj.Pathology = '';
                }
            }


        };
        $scope.OnselectPostProcedureNoteTemplates = function (item, type) {
            item.TemplateNotes = item.TemplateNotes || "";
            if (type == 'Discharge') {
                if (item.TemplateNotes != '') {
                    $scope.DischargeSummaryObj.PostProcedureNote = item.TemplateNotes || "";
                }
                else {
                    $scope.DischargeSummaryObj.PostProcedureNote = '';
                }
            } else {
                if (item.TemplateNotes != '') {
                    $scope.OperativeNotesObj.PostProcedureNotes = item.TemplateNotes || "";
                }
                else {
                    $scope.OperativeNotesObj.PostProcedureNotes = '';
                }
            }

        }
        $scope.OnselectPatientsInstructionTemplates = function (item) {
            item.TemplateNotes = item.TemplateNotes || "";
            if (item.TemplateNotes != '') {
                $scope.OperativeNotesObj.PatientsInstructions = item.TemplateNotes || "";
            }
            else {
                $scope.OperativeNotesObj.PatientsInstructions = '';
            }
        };
        $scope.OnselectFinaldispositionTemplates = function (item) {
            item.TemplateNotes = item.TemplateNotes || "";
            if (item.TemplateNotes != '') {
                $scope.DischargeSummaryObj.FinalDisposition = item.TemplateNotes || "";
            }
            else {
                $scope.DischargeSummaryObj.FinalDisposition = '';
            }
        };

        $scope.ChangeVitalsStatus = function (Type) {
            $scope.OperativeNotesObj.VitalsType = Type;
            var PatientAlert = '';
            var PatientVitalsStatus = '';
            if ($scope.OperativeNotesObj.PatientAlert) {
                PatientAlert = 'Patient is Alert and Oriented.';
            }
            PatientVitalsStatus = 'Vitals Are ' + $scope.OperativeNotesObj.VitalsType;
            $scope.OperativeNotesObj.PhysicalExam = PatientAlert + ' ' + PatientVitalsStatus;
        };
        $scope.OnSelectPatientAlert = function (Alert) {
            var PatientAlert = '';
            var PatientVitalsStatus = '';
            if (Alert) {
                PatientAlert = 'Patient is Alert and Oriented.';
            }
            if ($scope.OperativeNotesObj.VitalsType !== '') {
                PatientVitalsStatus = 'Vitals Are ' + $scope.OperativeNotesObj.VitalsType;
            }
            $scope.OperativeNotesObj.PhysicalExam = PatientAlert + ' ' + PatientVitalsStatus;
        };

        $scope.GetOperativeDischargeTemplates = function () {

            let req = {
                "OrganizationId": $scope.HospitalId,
                "UserId": $scope.UserId,
            };
            eHnoteSurgeryService.GetOperativeDischargeTemplates(req).then(function (resp) {
                if (resp.data.Status === "Success") {
                    $scope.DischargeSummaryObj.OverallDischargeTemplate = resp.data.Discharge || [];
                    $scope.OperativeNotesObj.OverallOperativeNotesTemplate = resp.data.FaceSheetOperative || [];
                }

            }, function (err) {
                console.log(err);
            });
        };

        $scope.SaveOverallDischargeTemplateData = function () {
            $scope.Templateobj.EnterOverallDischargeTemplateName = $scope.Templateobj.EnterOverallDischargeTemplateName || "";
            // $scope.DischargeSummaryObj.FinalDisposition = $scope.DischargeSummaryObj.FinalDisposition || "";
            if ($scope.Templateobj.EnterOverallDischargeTemplateName === "") {
                alertify.error("Please Enter Template Name!");
                return false;
            }
            //if ($scope.DischargeSummaryObj.FinalDisposition === "") {
            //    alertify.error("Please Enter Final Disposition");
            //    return false;
            //}
            let templateReq =
            {
                "UserId": $scope.UserId || "",
                "HospitalId": $scope.HospitalId || "",
                "TemplateId": 0,
                "TemplateName": $scope.Templateobj.EnterOverallDischargeTemplateName || "",
                "DeleteInd": "N",
                "TypeId": '1',
                "TypeName": 'Discharge',
                //"ProcedureDescription": $scope.DischargeSummaryObj.ProcedureDescription||"",
                //"ExaminationNotes": $scope.DischargeSummaryObj.ExaminationNotes||"",
                //"PostProceduresNotes": $scope.DischargeSummaryObj.PostProceduresNotes || "",
                //"Complications": $scope.DischargeSummaryObj.Complications || "",
                //"Pathology": $scope.DischargeSummaryObj.Pathology || "",
                //"DischargeInstruction": $scope.DischargeSummaryObj.DischargeInstruction || "",
                "PatientsInstructions": $scope.DischargeSummaryObj.PatientsInstructions || "",
                "FinalDisposition": $scope.DischargeSummaryObj.FinalDisposition || "",
                //"ReasonForVisit": $scope.DischargeSummaryObj.ReasonForVisit || "",
                "PatientConditionInstruction": $scope.DischargeSummaryObj.PatientConditionInstruction || "",
                "CoManagementInstruction": $scope.DischargeSummaryObj.CoManagementInstruction || "",
                "FollowUpInstructions": $scope.DischargeSummaryObj.FollowUpInstructions || "",
                "RoleId": $scope.RoleId
            };


            eHnoteSurgeryService.AddUpdateOperativeDischargeTemplates(templateReq).then(function (resp) {
                if (resp.data.Status === "Success") {
                    alertify.success("Template saved successfully!");
                    $scope.Templateobj.EnterOverallDischargeTemplateName = "";
                    $scope.Templateobj.IsOverallDischargeTemplateSavePopOver = false;
                    $scope.GetOperativeDischargeTemplates();

                }
                if (resp.data.Status === "Failure") {
                    alertify.error('TemplateName Already Exists')
                }
            }, function (err) {
                console.log(err);
            });
        };

        $scope.SaveOverallOperativeNotesTemplateData = function () {
            $scope.Templateobj.EnterOverallOperativeNotesTemplateName = $scope.Templateobj.EnterOverallOperativeNotesTemplateName || "";

            if ($scope.Templateobj.EnterOverallOperativeNotesTemplateName === "") {
                alertify.error("Please Enter Template Name!");
                return false;
            }

            let templateReq =
            {
                "UserId": $scope.UserId || "",
                "HospitalId": $scope.HospitalId || "",
                "TemplateId": 0,
                "TemplateName": $scope.Templateobj.EnterOverallOperativeNotesTemplateName || "",
                "DeleteInd": "N",
                "TypeId": '2',
                "TypeName": 'OperativeNotes',
                //"ReasonForVisit": $scope.OperativeNotesObj.ReasonForVisit || "",
                //"PhysicalExam": $scope.OperativeNotesObj.PhysicalExam||"",
                "ProcedureDetails": $scope.OperativeNotesObj.ProcedureDetails || "",
                "ExaminationNotes": $scope.OperativeNotesObj.Findings || "",
                //"PreProcedureNotes": $scope.OperativeNotesObj.PreProcedureNotes || "",
                "SurgeonOperativeNotes": $scope.OperativeNotesObj.SurgeonOperativeNotes || "",
                //"Pathology": $scope.OperativeNotesObj.Pathology || "",
                "Complications": $scope.OperativeNotesObj.Complications || "",
                "PostOpMedicationsNotes": $scope.OperativeNotesObj.PostOpMedicationsNotes || "",
                "IsPostOpMedications":$scope.OperativeNotesObj.IsPostOpMedications||false,
                //"PostProceduresNotes": $scope.OperativeNotesObj.PostProcedureNotes || "",
                //"PatientsInstructions": $scope.OperativeNotesObj.PatientsInstructions || "",
                "RoleId": $scope.RoleId,
                "OccularHistory": $scope.obj.OccularHistoryArray || [],
                "OccularHistoryRemarks": $scope.obj.OccularHistoryRemarks || "",


            };


            eHnoteSurgeryService.AddUpdateOperativeDischargeTemplates(templateReq).then(function (resp) {
                if (resp.data.Status === "Success") {
                    alertify.success("Template saved successfully!");
                    $scope.Templateobj.EnterOverallOperativeNotesTemplateName = "";
                    $scope.Templateobj.IsOverallOperativeNotesTemplateSavePopOver = false;
                    $scope.GetOperativeDischargeTemplates();

                }
                if (resp.data.Status === "Failure") {
                    alertify.error('TemplateName Already Exists')
                }
            }, function (err) {
                console.log(err);
            });
        };

