        $scope.ClearPrescription = function (item, index) {
            if (item.PatientPrescriptionId != 0) {
                item.DeleteInd = "Y";

                if ($scope.OperativeNotesObj.Prescriptions.length > 0) {
                    var Preslist = $filter("filter")($scope.OperativeNotesObj.Prescriptions[0].PrescriptionDetails, { "DeleteInd": "N" }, true);
                    Preslist = Preslist || [];
                    if (Preslist.length === 0) {
                        angular.forEach($scope.OperativeNotesObj.Prescriptions, function (item) {
                            item.DeleteInd = "Y";
                        });
                    }
                }
            } else {
                if ($scope.OperativeNotesObj.Prescriptions.length > 0) {
                    var Prescriptlist = $filter("filter")($scope.OperativeNotesObj.Prescriptions[0].PrescriptionDetails, { "MedicationId": item.MedicationId }, true);
                    Prescriptlist = Prescriptlist || [];
                    if (Prescriptlist.length > 0) {
                        $scope.OperativeNotesObj.Prescriptions[0].PrescriptionDetails.splice(index, 1);
                    }
                    if ($scope.OperativeNotesObj.Prescriptions[0].PrescriptionDetails.length === 0) {
                        $scope.OperativeNotesObj.Prescriptions = [];
                    }
                }
            }
        }

