        $scope.clearSignDetails = function (type, id) {
            alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>This will delete the existing signature. Do you want to continue?</h4>", function () {
                var canvas = document.getElementById(id);
                var context = canvas.getContext('2d');
                context.clearRect(0, 0, canvas.width, canvas.height);

                if (type == 'PatientSignature') {
                    $scope.DischargeSummaryObj.PatientSignString = '';
                    $scope.DischargeSummaryObj.IsPatientSignatureDone = false;
                    $scope.DischargeSummaryObj.PatientSignedDateTime = null;
                }
                if (type == 'NurseSignature') {
                    $scope.DischargeSummaryObj.NurseSignString = '';
                    $scope.DischargeSummaryObj.IsNurseSignatureDone = false;
                    $scope.DischargeSummaryObj.SignatureNurseId = 0;
                    $scope.DischargeSummaryObj.SignatureNurseName = '';
                    $scope.DischargeSummaryObj.NurseSignedDateTime = null;
                }
                if (type == 'AccompaniedBySignature') {
                    $scope.DischargeSummaryObj.AccompaniedBySignString = '';
                    $scope.DischargeSummaryObj.IsAccompaniedBySignatureDone = false;
                    $scope.DischargeSummaryObj.AccompainedBy = '';
                    $scope.DischargeSummaryObj.AccompainedByNotes = '';
                    $scope.DischargeSummaryObj.DischargeAccompainedName = '';
                    $scope.DischargeSummaryObj.AccompaniedByDateTime = null;
                }
                $scope.$apply();
            });
        }

      

        $scope.GetAppointmentImages = function (Id) {
            var AppointmentId = Id || 0;
            var req = {
                "AppointmentId": AppointmentId
            };
            eHnoteSurgeryService.GetAppointmentImagesData(req).then(function (resp) {
                if (resp.data.status === "Success") {
                    if (resp.data.rows.length > 0) {
                        angular.forEach(resp.data.rows, function (item) {
                            item.IsPreviousFile = true;
                            if (item.FileTypeId == 36) {
                                if ($scope.pentaCamReportImages.length > 0) {
                                    let ImagesList = $filter("filter")($scope.pentaCamReportImages, function (kitem) { return kitem.DocumentId == item.DocumentID }, true);
                                    if (ImagesList.length == 0) {
                                        item.DocumentId = item.DocumentID;
                                        $scope.pentaCamReportImages.push(item);
                                    }
                                } else {
                                    item.DocumentId = item.DocumentID;
                                    $scope.pentaCamReportImages.push(item);
                                }
                            };
                            if (item.FileTypeId == 33) {
                                if ($scope.HealthPhysicalObj.DocumentDetails.length > 0) {
                                    let ImagesList = $filter("filter")($scope.HealthPhysicalObj.DocumentDetails, function (kitem) { return kitem.DocumentID == item.DocumentID }, true);
                                    if (ImagesList.length == 0) {
                                        $scope.HealthPhysicalObj.DocumentDetails.push(item);
                                    }
                                } else {
                                    $scope.HealthPhysicalObj.DocumentDetails.push(item);
                                }
                            };
                        });
                    }
                    
                }
            });
        };
        $scope.addAllergy = function (allergy) {
            allergy = allergy || "";
            if (allergy == '') {
                return false;
            }
            var reqObj = {
                "ParentOrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID,
                "OrganizationId": $scope.HospitalId,
                //"HospitalId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID,
                "UserId": doctorinfo.doctorid,
                "AllergyId": 0,
                "AllergyName": allergy,
                "AllergyTypeId": 13,
                "Reaction": "",
                "DeleteInd": false,
                "ModifiedBy": $scope.DisplayName,
                "ModifiedDt": $scope.DisplayDate
            };
            eHnoteDiagnosisDataServices.addAllergy(reqObj).then(function (response) {
                if (response.data.Status === "Success") {
                    $scope.onAllergySelect(response.data.rows[0]);
                    $scope.ROSHistoriesObj.AddAllergyshow = false;
                }
                if (response.Status === 'Failure') {
                    alertify.error(response.data.Message);
                }
            });
        };
