                    "Remarks": $scope.obj.SelectedOcularHistoryItem.Remarks || "",
                    "ShowNote": false,
                    "RDuration": "",
                    "RDurationType": "D",
                    "RDurationTypeName": "Day(s)",
                    "RSeverityDateTime": $filter('date')(new Date(), "MM-dd-yyyy h:mm a"),
                    "RDurationDate": "",
                    "RShowDateFormat": true,
                    "RSeverityId": "",
                    "RStatusId": 1,
                    "RStatusName": 'Active',
                    "RSeverityName": "",
                    "LDuration": "",
                    "LDurationType": "D",
                    "LDurationTypeName": "Day(s)",
