        $scope.GetAllFrequentlyAddedData = function () {
            var allrgireq = {
                "HospitalId": $scope.HospitalId,
                "PageSize": 30,
                "PageNumber": 1,
                "UserId": doctorinfo.doctorid,
                "IsFrequent": "Y"

            };
            eHnoteDiagnosisDataServices.GetAllFrequentlyAddedData(allrgireq).then(function (resp) {

                if (resp.data.Status === "Success") {

                    $scope.FrequentlyOccularHIstory = resp.data.OccularHIstory || [];
                    angular.forEach($scope.FrequentlyOccularHIstory, function (item) {
                        item.Onselect = false;
                    });

                    if ($scope.obj.OccularHistoryArray.length > 0) {
                        angular.forEach($scope.obj.OccularHistoryArray, function (item) {
                            if (item.DeleteInd == 'N') {
                                var FreqList = $filter("filter")($scope.FrequentlyOccularHIstory, function (fitem) {
                                    return fitem.HistoryId == item.HistoryId;
                                }, true) || [];
                                if (FreqList.length > 0) {
                                    FreqList[0].Onselect = true;
                                }
                            }
                        });
                    }

                }
            })
        }
        $scope.OccularHistorySnomedICD10Code = function (item, type) {
            if (type == 'SNOMEDCODE') {
                item.IsShowoccularHistorySnomedAddInd = !item.IsShowoccularHistorySnomedAddInd;
            }
            if (type == 'ICD10CODE') {
                item.IsShowoccularHistoryICD10CODEAddInd = !item.IsShowoccularHistoryICD10CODEAddInd;
            }
        }
        $scope.AddUpdateOccularHistorySnomedICD10Code = function (item, type) {
            if (type == 'SNOMEDCODE') {
                if (item.AddSNOMED == "" || item.AddSNOMED == undefined) {
                    alertify.error("Please Enter Snomad code ");
                    return false;
                }
            }
            if (type == 'ICD10CODE') {
                if (item.AddICD10CODE == "" || item.AddICD10CODE == undefined) {
                    alertify.error("Please Enter ICD10 code ");
                    return false;
                }
            }
            if (item.SNOMEDCODE != "" && item.SNOMEDCODE != undefined) {
                item.AddSNOMED = item.SNOMEDCODE;
            }
            if (item.ICD10CODE != "" && item.ICD10CODE != undefined) {
                item.AddICD10CODE = item.ICD10CODE;
            }

            var object = {
                "ParentOrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID,
                "OrganizationId": $scope.HospitalId,

                "UserId": $scope.UserId || "",
                "DeleteInd": false,
                "DiagnosisId": item.DiagnosisId || "",
                "ICD10CODE": item.AddICD10CODE || "",
                "SNOMED": item.AddSNOMED || "",       // ConceptId
                "SNOMEDId": item.SNOMEDId || "",  // SnomedCodeId
                "HistoryName": item.HistoryName || "",
                "HistoryId": item.HistoryId || "",
                "IsFrequent": item.IsFrequent || 'N',
            };
            eHnoteSettingsDataService.AddUpdateMasterOccularHistory(object).then(function (response) {
                if (response.data.Status === "Success") {
                    if (type == 'SNOMEDCODE') {
                        alertify.success("Ocular History Snomed code added Successfully");
                        item.IsShowoccularHistorySnomedInd = !item.IsShowoccularHistorySnomedAddInd;
                        item.IsShowoccularHistorySnomedAddInd = !item.IsShowoccularHistorySnomedAddInd;
                    }
                    if (type == 'ICD10CODE') {
                        alertify.success("Ocular History ICI10  code added Successfully");
                        item.IsShowoccularHistoryICD10CODEInd = !item.IsShowoccularHistoryICD10CODEInd;
                        item.IsShowoccularHistoryICD10CODEAddInd = !item.IsShowoccularHistoryICD10CODEAddInd;
                    }
                    if (item.AddSNOMED != "" && item.AddSNOMED != undefined) {
                        item.SNOMEDCODE = item.AddSNOMED || "";
                    }
                    if (item.AddICD10CODE != "" && item.AddICD10CODE != undefined) {
                        item.ICD10CODE = item.AddICD10CODE || "";
                    }
                }
                if (response.data.Status === 'Failure') {
                    alertify.success("Ocular History   code added failed");
                }
            });
        }
