        $scope.LastVisitData = function () {
            eHnotePatientDataService.GetMedicalHistoriesByPatientId($scope.cacheStorageItem.PatientID).then(function (resp) {
                resp.data = resp.data || '';
                if (resp.data !== '') {
                    resp.data.rows = resp.data.rows || [];
                    if (resp.data.rows.length > 0) {


                        $scope.OccularHistoryArray = resp.data.rows[0].OccularHistory || [];

                        if ($scope.OccularHistoryArray.length > 0) {
                            angular.forEach($scope.OccularHistoryArray, function (ohitem) {
                                if (ohitem.RStatusId == 1 || ohitem.LStatusId == 1) {
                                    var isDuplicate = $scope.obj.OccularHistoryArray.some(function (existingItem) {
                                        return existingItem.HistoryId === ohitem.HistoryId;
                                    });

                                    if (!isDuplicate) {
                                        var object = {
                                            "PatientDetailId": 0,
                                            "HistoryId": ohitem.HistoryId,
                                            "HistoryName": ohitem.HistoryName,
                                            "IsEdit": false,
                                            "showOccularHistory": false,
                                            "ActiveInd": true,
                                            "DeleteInd": 'N',
                                            "Remarks": ohitem.Remarks || "",
                                            "DiagnosisId": ohitem.DiagnosisId || "",
                                            "DiagnosisObject": ohitem.ICD10CODE || "",
                                            "ICD10CODE": ohitem.ICD10CODE || "",
                                            "SNOMEDCODE": ohitem.SNOMED || "",
                                            "SNOMEDId": ohitem.SNOMEDId || "",
                                            "ShowNote": !!ohitem.Remarks,
                                            "RDuration": ohitem.RDuration || "",
                                            "RDurationType": ohitem.RDurationType || "D",
                                            "RDurationTypeName": ohitem.RDurationTypeName || "Day(s)",
                                            "RSeverityDateTime": ohitem.RSeverityDateTime,
                                            "RDurationDate": ohitem.RDurationDate,
                                            "RShowDateFormat": ohitem.RDuration === "",
                                            "RSeverityId": ohitem.RSeverityId || "",
                                            "RStatusId": ohitem.RStatusId || 1,
                                            "RStatusName": ohitem.RStatusName || 'Active',
                                            "RSeverityName": ohitem.RSeverityName || "",
                                            "LDuration": ohitem.LDuration || "",
                                            "LDurationType": ohitem.LDurationType || "D",
                                            "LDurationTypeName": ohitem.LDurationTypeName || "Day(s)",
                                            "LSeverityDateTime": ohitem.LSeverityDateTime || "",
                                            "LDurationDate": ohitem.LDurationDate || "",
                                            "LShowDateFormat": ohitem.LDuration === "",
                                            "LSeverityId": ohitem.LSeverityId || 0,
                                            "LStatusId": ohitem.LStatusId || 0,
                                            "LStatusName": ohitem.LStatusName || '',
                                            "LSeverityName": ohitem.LSeverityName || "",
                                            "IsBothEye": ohitem.IsBothEye || false,
                                            "IsFrequent": ohitem.IsFrequent || "N"
                                        };

                                        $scope.obj.OccularHistoryArray.push(object);
                                    }
                                }
                            });

                            angular.forEach($scope.obj.OccularHistoryArray, function (item) {
                                item.IsEdit = false;

                                if (item.RDurationDate) {
                                    item.RDurationDate = $filter('date')(item.RDurationDate, "MM-dd-yyyy");
                                }
                                if (item.LDurationDate) {
                                    item.LDurationDate = $filter('date')(item.LDurationDate, "MM-dd-yyyy");
                                }

                                if (item.RDurationType === "SB") {
                                    item.RShowDateFormat = false;
                                }
                                if (item.LDurationType === "SB") {
                                    item.LShowDateFormat = false;
                                }
                            });

                            var list = $filter("filter")($scope.obj.OccularHistoryArray, { "HistoryId": 1 }, true);
                            if (list.length > 0) {
                                angular.forEach(list, function (item) {
                                    if (item.PatientDetailId === 0) {
                                        var indexToRemove = $scope.obj.OccularHistoryArray.indexOf(item);
                                        if (indexToRemove !== -1) {
                                            $scope.obj.OccularHistoryArray.splice(indexToRemove, 1);
                                        }
                                    } else {
                                        item.DeleteInd = 'Y';
                                    }
                                });
                            }
                        }
                    };
                };
            }, function (err) {
                alertify.error(err.data.ExceptionMessage);
            });
        }
        $scope.AddNewOccularHistory = function (SelectedOccularHistory) {
            SelectedOccularHistory = SelectedOccularHistory || "";
            if (SelectedOccularHistory === "") {
                alertify.error("Enter OccularHistory");
                return;
            }
            var object = {
                "ParentOrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID,
                "OrganizationId": $scope.HospitalId,
                "UserId": doctorinfo.doctorid,
                "DeleteInd": false,
                "HistoryName": SelectedOccularHistory,
                "HistoryId": 0
            };
            eHnoteSettingsDataService.AddUpdateMasterOccularHistory(object).success(function (response) {
                if (response.Status === 'Success') {
                    if (response.count > 0) {
                        $scope.SelectedOccularHistory = "";
                        SelectedOccularHistory = "";
                        $scope.onRosOccularHistoryBlurChange(response.OccularHistory[0]);
                        $scope.ROSHistoriesObj.AddOccularHistory = false;
                        alertify.success("Successfully Added");
                    }
                }
                if (response.Status === 'Failure') {
                    alertify.error(response.Message);
                    $scope.SelectedOccularHistory = "";
                    SelectedOccularHistory = "";
                }
            })
                .error(function (error) {
                    alertify.error("Error Occured");
                });
        };
