        $scope.SaveForceEarlySignOffRemarks = function () {
            $scope.DischargeSummaryObj.DischargeStopTimerRemarks = $scope.DischargeSummaryObj.DischargeStopTimerRemarks || '';
            if ($scope.DischargeSummaryObj.DischargeStopTimerRemarks == '') {
                alertify.error("Please Enter Remarks");
                return false;
            }
            var CurrentTime = $filter("date")(new Date(), "h:mm a");
            var Param = {
                "AppointmentID": $scope.cacheStorageItem.AppointmentId,
                "UserId": $scope.UserId,
                "HospitalId": $scope.HospitalId,
                "StartTimer": $scope.DischargeSummaryObj.DischargeSignOffStartTime,
                "EndTimer": CurrentTime,
                "Remarks": $scope.DischargeSummaryObj.DischargeStopTimerRemarks,
                "DischargeStartTimeUser": $scope.DischargeSummaryObj.DischargeStartTimeUser || null,
                "DischargeEndTimeUser": $scope.UserId,
            }
            eHnoteSurgeryService.AddUpdateDischargeSignOffTimer(Param).then(function (response) {
                if (response.data.Status === "Success") {
                    $scope.DischargeSummaryObj.IsShowForceEarlySignOffPopover = false;
                    $scope.GetPostOpDischargeData();
                }
                if (response.data.Status === 'Failure') {
                    alertify.error(response.data.Message);
                }
            })
        };
        $scope.GetPostOpDischargeData = function () {

            let PatientSurgeryId = null;
            if ($scope.cacheStorageItem.AppointmentTypeId == 7) {
                if ($scope.cacheStorageItem.PreAdmSurgeryList.length > 0) {
                    PatientSurgeryId = $scope.cacheStorageItem.PreAdmSurgeryList[0].PatientSurgeryId;
                }
            } else if ($scope.cacheStorageItem.AppointmentTypeId == 4 || $scope.cacheStorageItem.AppointmentTypeId == 14) {
                if ($scope.cacheStorageItem.SurgeryList.length > 0) {
                    PatientSurgeryId = $scope.cacheStorageItem.SurgeryList[0].PatientSurgeryId;
                }
            }
            var Obj = {
                "OrganizationId": $scope.HospitalId,
                "AppointmentId": $scope.FaceSheetAppointmentId || null,
                "PatientId": $scope.cacheStorageItem.PatientID || null,
                "PatientSurgeryId": PatientSurgeryId || null,
            }
            eHnoteSurgeryService.GetPostOpDischargeData(Obj).then(function (response) {
                if (response.data.Status === "Success") {
                    $scope.DischargeSummaryObj.DischargeSignOffStartTime = response.data.DischargeSignOffStartTime || '';
                    $scope.DischargeSummaryObj.DischargeSignOffEndTime = response.data.DischargeSignOffEndTime || '';
                    $scope.DischargeSummaryObj.DischargeStartTimeUser = response.data.DischargeStartTimeUser || null;
                    $scope.DischargeSummaryObj.DischargeEndTimeUser = response.data.DischargeEndTimeUser || null;
                    $scope.DischargeSummaryObj.DischargeStopTimerRemarks = response.data.DischargeStopTimerRemarks || null;

                    $scope.DischargeSummaryObj.IsShowForceEarlySignOffButton = false;

                    $scope.PostOpDischargeSignOff();
                }
            })
        };
        $scope.ShowTimer = function (StartTimerTime, DurationInMinutes) {
            var StartTime = StartTimerTime || '';
            var Duration = (parseFloat(DurationInMinutes) || 0) * 60 * 1000; // convert minutes to ms

            if (DurationInMinutes !== '') {
                const interval = $interval(function () {
                    const now = new Date();
                    var todayString = now.toDateString(); // e.g., "Mon Nov 11 2025"
                    var startTimer = new Date(todayString + ' ' + StartTime);
                    const diff = now - startTimer; // elapsed time in ms

                    // if elapsed >= given duration, stop timer
                    if (Duration > 0 && diff >= Duration) {
                        $scope.DischargeSummaryObj.DischargeTimerStartTime = $scope.DischargeSummaryObj.DischargeSignOffEndTime;
                        $scope.DischargeSummaryObj.IsShowForceEarlySignOffButton = false;
                        $scope.DischargeSummaryObj.IsTimerStoped = true;
                        $interval.cancel(interval);
                    } else {
                        $scope.DischargeSummaryObj.DischargeTimerStartTime = diff;
                    }
                }, 1000);
            }
        };


